
import { shopAreas, prefectures } from '../../../mocks/shops';

interface AreaSelectorProps {
  selectedArea: string;
  selectedPrefecture: string;
  onAreaChange: (area: string) => void;
  onPrefectureChange: (pref: string) => void;
}

export default function AreaSelector({
  selectedArea,
  selectedPrefecture,
  onAreaChange,
  onPrefectureChange,
}: AreaSelectorProps) {
  return (
    <div className="bg-white border border-gray-200 rounded-xl p-5">
      <h3 className="font-bold text-gray-900 mb-4 flex items-center gap-2 text-sm">
        <i className="ri-map-2-line text-red-500 w-5 h-5 flex items-center justify-center"></i>
        エリアから探す
      </h3>

      <div className="space-y-1.5">
        <button
          onClick={() => {
            onAreaChange('');
            onPrefectureChange('');
          }}
          className={`w-full text-left py-2.5 px-3 rounded-lg text-sm font-medium transition-colors cursor-pointer ${
            selectedArea === ''
              ? 'bg-red-600 text-white'
              : 'bg-gray-50 text-gray-700 hover:bg-red-50 hover:text-red-600'
          }`}
        >
          全国
          <span className="float-right text-xs opacity-80">
            {shopAreas.reduce((sum, a) => sum + a.count, 0)}件
          </span>
        </button>

        {shopAreas.map((area) => (
          <div key={area.id}>
            <button
              onClick={() => {
                onAreaChange(area.id === selectedArea ? '' : area.id);
                onPrefectureChange('');
              }}
              className={`w-full text-left py-2.5 px-3 rounded-lg text-sm font-medium transition-colors cursor-pointer flex items-center justify-between ${
                selectedArea === area.id
                  ? 'bg-red-600 text-white'
                  : 'bg-gray-50 text-gray-700 hover:bg-red-50 hover:text-red-600'
              }`}
            >
              <span>{area.name}</span>
              <span className="text-xs opacity-80">{area.count}件</span>
            </button>

            {/* 都道府県展開 */}
            {selectedArea === area.id && prefectures[area.id] && (
              <div className="ml-3 mt-1 space-y-0.5">
                {prefectures[area.id].map((pref) => (
                  <button
                    key={pref}
                    onClick={() =>
                      onPrefectureChange(pref === selectedPrefecture ? '' : pref)
                    }
                    className={`w-full text-left py-2 px-3 rounded-md text-xs transition-colors cursor-pointer ${
                      selectedPrefecture === pref
                        ? 'bg-red-100 text-red-700 font-bold'
                        : 'text-gray-600 hover:bg-gray-100'
                    }`}
                  >
                    {pref}
                  </button>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}
